// LoanFormPage.tsx (Loan Entry Form Page)
import React, { useState } from 'react';
import { useRouter } from 'next/router';

// Type for customer
interface Customer {
  name: string;
  phone: string;
  district: string;
  loanAmount: number;
  dueDate: string;
  balance: number;
  selfie: string;
}

const LoanFormPage = () => {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [district, setDistrict] = useState('');
  const [loanAmount, setLoanAmount] = useState(0);
  const [dueDate, setDueDate] = useState('');
  const [selfie, setSelfie] = useState('');
  const router = useRouter();

  const handleSelfieChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelfie(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const newCustomer: Customer = {
      name,
      phone,
      district,
      loanAmount,
      dueDate,
      balance: loanAmount,
      selfie,
    };

    // Save the customer data in local storage or a global state (for simplicity, using local storage here)
    localStorage.setItem('customerData', JSON.stringify(newCustomer));

    // Redirect to the customer page
    router.push('/customer');
  };

  return (
    <div className="p-6">
      <h1 className="text-3xl font-semibold mb-6">Loan Application Form</h1>
      <form onSubmit={handleSubmit} className="bg-white shadow-lg rounded-md p-6">
        <input
          type="text"
          placeholder="Customer Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="mb-4 p-3 w-full border border-gray-300 rounded-md"
        />
        <input
          type="tel"
          placeholder="Phone Number"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          className="mb-4 p-3 w-full border border-gray-300 rounded-md"
        />
        <input
          type="text"
          placeholder="District"
          value={district}
          onChange={(e) => setDistrict(e.target.value)}
          className="mb-4 p-3 w-full border border-gray-300 rounded-md"
        />
        <input
          type="number"
          placeholder="Loan Amount"
          value={loanAmount}
          onChange={(e) => setLoanAmount(Number(e.target.value))}
          className="mb-4 p-3 w-full border border-gray-300 rounded-md"
        />
        <input
          type="date"
          value={dueDate}
          onChange={(e) => setDueDate(e.target.value)}
          className="mb-4 p-3 w-full border border-gray-300 rounded-md"
        />
        <input
          type="file"
          accept="image/*"
          onChange={handleSelfieChange}
          className="mb-4 p-3 w-full border border-gray-300 rounded-md"
        />
        <button
          type="submit"
          className="bg-blue-500 text-white py-3 px-6 rounded-md w-full"
        >
          Submit Loan Application
        </button>
      </form>
    </div>
  );
};

export default LoanFormPage;
